{-# INLINE encodedScriptExtensions #-}
encodedScriptExtensions :: Char -> Int#
encodedScriptExtensions c
    -- Planes 0-3
    | cp < 0x3FC40 = lookupEncodedScriptExtensionsBitMap cp#
    -- Planes 4-13: 171
    | cp < 0xE0000 = 171#
    -- Plane 14
    | cp < 0xE01F0 = lookupEncodedScriptExtensionsBitMap (cp# -# 0xA03C0#)
    -- Default: 171
    | otherwise = 171#
    where
    !cp@(I# cp#) = ord c

{-# INLINE lookupEncodedScriptExtensionsBitMap #-}
lookupEncodedScriptExtensionsBitMap :: Int# -> Int#
